-- XDG Desktop Portal
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
-- XDG_CONFIG_HOME / XDG_DATA_HOME are deliberately NOT set here.
--
-- They used to be, as `env = XDG_CONFIG_HOME,~/.config`. Hyprland does
-- NOT expand `~` in an `env =` line -- it exports the value verbatim --
-- so every process in the session inherited the literal seven-character
-- string `~/.config` as its config root. Programs that hand that to a
-- libc/glib path helper were fine (glib rejects a non-absolute
-- XDG_CONFIG_HOME and silently falls back to $HOME/.config); programs
-- that just concatenate were not.
--
-- wlogout concatenates: it looks for "$XDG_CONFIG_HOME/wlogout/layout",
-- got the RELATIVE path `~/.config/wlogout/layout`, missed, and fell
-- through to /etc/wlogout/{layout,style.css} -- which is why the session
-- menu came up as the stock six-button KDE-looking grid instead of the
-- four-icon one in ~/.config/wlogout. It was never a theming problem.
--
-- The literal `~` directories scattered around $HOME (~/.config/eww/~,
-- ~/.config/hypr/conf/~, ~/Desktop/~, ...) are the same bug writing
-- files: a program resolved `~/.config/...` against its own cwd.
--
-- Unset is not a workaround, it is the correct value: the XDG basedir
-- spec defines the defaults as exactly $HOME/.config and
-- $HOME/.local/share, so setting them bought nothing even when the
-- string was right.
-- QT
hl.env("QT_QPA_PLATFORM", "wayland")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "1")

-- GTK
hl.env("GDK_SCALE", "1")

-- Mozilla
hl.env("MOZ_ENABLE_WAYLAND", "1")

hl.env("BROWSER", "firefox")
hl.env("DEFAULT_BROWSER", "firefox")
hl.env("CHROME_DESKTOP", "firefox.desktop")

-- Set the cursor size for xcursor
hl.env("XCURSOR_SIZE", "24")

-- Disable appimage launcher by default
hl.env("APPIMAGELAUNCHER_DISABLE", "1")

-- nvidia crap
hl.env("GBM_BACKEND", "nvidia-drm")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("LIBVA_DRIVER_NAME", "nvidia")

